import { Scene } from "@babylonjs/core/scene.js";
import { Engine } from "@babylonjs/core/Engines/engine.js";
import { EngineStore } from "@babylonjs/core/Engines/engineStore.js";
import { Vector2, Vector3, Color3 } from "@babylonjs/core/Maths/math.js";
import { MeshBuilder } from "@babylonjs/core/Meshes/meshBuilder.js"
import { Mesh } from "@babylonjs/core/Meshes/mesh.js";
import { StandardMaterial } from '@babylonjs/core/Materials/standardMaterial.js';
import { Texture } from '@babylonjs/core/Materials/Textures/texture.js';
import { AdvancedDynamicTexture } from "@babylonjs/gui/2D/advancedDynamicTexture.js";
import { Observable } from "@babylonjs/core/Misc/observable.js";

import Tile from './Tile.js';
import TileMath, { EPSG_Type } from './TileMath.js';
import Attribution from "./Attribution.js";
import type Buildings from '../buildings/Buildings.js';
import type TileBuilding from "./TileBuilding.js";

import "@babylonjs/core/Materials/standardMaterial.js"
import Raster from "../raster/Raster.js";
import RasterOSM from "../raster/RasterOSM.js";
import TerrainMB from "../terrain/TerrainMB.js";
import { RetrievalLocation } from "../shared/Retrieval.js";

export { RetrievalLocation, RetrievalType } from "../shared/Retrieval.js";

enum TileRequestType {
    LoadTile,
}

export interface TileRequest {
    requestType: TileRequestType
    tile: Tile;
    tileCoords: Vector3;
    url: string;
    mesh: Mesh;
    texture: Texture | null;
    inProgress: boolean;
}

/**
 * Describes a tile that was recycled by moveAllTiles().
 *
 * The coordinate vectors are snapshots. Consumers can use the old coordinate
 * to remove their content and the new coordinate to create replacement
 * content without retaining mutable TileSet state.
 */
export interface TilePositionUpdate {
    tile: Tile;
    previousTileCoords: Vector3;
    tileCoords: Vector3;
}

export interface TileSetOptimizationOptions {
    /** Freeze raster materials after their texture is ready. */
    freezeRasterMaterials?: boolean;
    /** Freeze tile world matrices. Only use this when tiles never move. */
    freezeTileWorldMatrices?: boolean;
    /** Disable picking on raster tile meshes. */
    disableTilePicking?: boolean;
    /** Disable collision checks on raster tile meshes. */
    disableTileCollisions?: boolean;
}

export const DEFAULT_TILESET_OPTIMIZATION_OPTIONS: Readonly<Required<TileSetOptimizationOptions>> = {
    freezeRasterMaterials: true,
    freezeTileWorldMatrices: false,
    disableTilePicking: false,
    disableTileCollisions: false,
};
export default class TileSet {
    /** Projection hooks shared by all feature and terrain providers. */
    public readonly isGlobe: boolean = false;
    public isTileGeometryReady(_tile: Tile): boolean { return true; }
    public getGeometryMath(): TileMath { return this.ourTileMath; }
    public projectFeatureMesh(_mesh: Mesh): void {}
    public applyElevationGrid(_tile: Tile, _heights: number[], _precision: number): void {}


    private xmin: number;
    private zmin: number;
    private xmax: number;
    private zmax: number;

    public ourTiles: Tile[] = [];
    public ourTilesMap: Map<string, Tile> = new Map();

    public doRasterResBoost = true;
    public doTerrainResBoost = false;

    public zoom = 0;
    private tileCorner: Vector2;
    public centerCoords: Vector2;
    public tileScale: number;
    public hasAlpha = false;

    public streetExtensionAmount = 0.25; //TODO; fix this to be in some sort of units that make sense, instead of game-world coordinates. 

    private ourRasterProvider: Raster;
    private rasterVersion = 0;
    private tileRasterVersion = new WeakMap<Tile, number>();
    //private accessToken: string;

    public ourTerrainMB: TerrainMB;
    private totalWidthMeters: number;
    private totalHeightMeters: number;
    public ourAttribution: Attribution;
    public ourTileMath: TileMath;

    protected tileRequests: TileRequest[] = [];
    protected requestsProcessedSinceCaughtUp = 0;
    public onCaughtUpObservable: Observable<boolean> = new Observable;
    /** Notifies after moveAllTiles() assigns a recycled tile its new coordinates. */
    public onTilePositionUpdatedObservable: Observable<TilePositionUpdate> = new Observable;

    public numTiles: Vector2;
    public tileWidth: number;
    public meshPrecision: number;
    /** Controls optional raster/tile mesh optimizations. */
    public optimizationOptions: Required<TileSetOptimizationOptions> = {
        ...DEFAULT_TILESET_OPTIMIZATION_OPTIONS,
    };
    private isGeometrySetup: boolean = false;
    private isRasterSetup: boolean = false;

    /**
    * this doesn't do much, just sets up a linkage between our library and users main project
    * @param scene the babylonjs scene, helps us get around a bug, where the main app and the library are in 2 different contexts
    * @param engine see above description for scene
    */
    constructor(public scene: Scene, private engine: Engine) {

        EngineStore._LastCreatedScene = this.scene; //gets around a babylonjs bug where we aren't in the same context between the main app and the mapping library
        if (!EngineStore.Instances.includes(this.engine)) {
            EngineStore.Instances.push(this.engine);
        }

        this.ourAttribution = new Attribution(this.scene);
        this.ourTileMath = new TileMath(this);

        this.setRasterProvider(new RasterOSM(this)); //set default raster basemap to OSM
        this.ourTerrainMB = new TerrainMB(this, this.scene); //TODO: this should really be a terrain provider, in case we can get terrain from more than just MapBox


        this.scene.onBeforeRenderObservable.add(() => { //fire every frame
            this.processTileRequests(); //TODO: investigate WebWorker or other "threading" techniques, instead of calling every frame
        });
    }

    /**
     * Returns whether the tile meshes have been created and are ready for use.
     */
    public get isGeometryCreated(): boolean {
        return this.isGeometrySetup;
    }

    /**
     * Guard operations that require createGeometry() to have run first.
     */
    public assertGeometrySetup(operation = "this operation"): void {
        if (!this.isGeometrySetup) {
            throw new Error(`Cannot ${operation} before createGeometry() has been called.`);
        }
    }

    /**
     * Guard operations that also require tile coordinates from updateRaster().
     */
    public assertRasterSetup(operation = "this operation"): void {
        this.assertGeometrySetup(operation);
        if (!this.isRasterSetup) {
            throw new Error(`Cannot ${operation} before updateRaster() has been called.`);
        }
    }

    /** Merges tile optimization settings and applies them to existing tiles. */
    public setOptimizationOptions(options: TileSetOptimizationOptions): void {
        this.optimizationOptions = {
            ...this.optimizationOptions,
            ...options,
        };
        this.applyOptimizationOptions();
    }

    /** Applies picking, collision, world-matrix, and material settings. */
    public applyOptimizationOptions(): void {
        for (const tile of this.ourTiles) {
            tile.mesh.isPickable = !this.optimizationOptions.disableTilePicking;
            tile.mesh.checkCollisions = !this.optimizationOptions.disableTileCollisions;
            tile.mesh.computeWorldMatrix(true);

            if (this.optimizationOptions.freezeTileWorldMatrices) {
                tile.mesh.freezeWorldMatrix();
            } else {
                tile.mesh.unfreezeWorldMatrix();
            }

            if (tile.material) {
                if (this.optimizationOptions.freezeRasterMaterials) {
                    tile.material.freeze();
                } else {
                    tile.material.unfreeze();
                }
            }
        }
    }

    /**
    * setup a ground plane tile set. this sets up just the underlying meshes, but doesn't populate them with content yet
    * @param numTiles how many tiles in the x and y directions
    * @param tileWidth width in meters of a single tile
    * @param meshPrecision how many numTiles in each tile's mesh. need more for terrain type meshes, less if no height change on mesh. 
    */
    public createGeometry(numTiles: Vector2, tileWidth: number, meshPrecision: number) {
        //inspiration from this example: https://www.babylonjs-playground.com/#866PVL#5

        if (!Number.isInteger(numTiles.x) || !Number.isInteger(numTiles.y) || numTiles.x <= 0 || numTiles.y <= 0) {
            throw new RangeError("numTiles.x and numTiles.y must be positive integers.");
        }
        if (!Number.isFinite(tileWidth) || tileWidth <= 0) {
            throw new RangeError("tileWidth must be a finite number greater than zero.");
        }
        if (!Number.isInteger(meshPrecision) || meshPrecision <= 0) {
            throw new RangeError("meshPrecision must be a positive integer.");
        }

        if (this.isGeometrySetup) {
            for (const tile of this.ourTiles) {
                tile.deleteBuildings();
                tile.clearTerrainLOD();
                tile.material?.dispose(false, true);
                tile.mesh.dispose();
            }
            this.ourTiles = [];
            this.ourTilesMap.clear();
            this.clearTileRequests();
        }
        this.isRasterSetup = false;

        this.numTiles = numTiles.clone();
        this.tileWidth = tileWidth;
        this.meshPrecision = meshPrecision;

        this.totalWidthMeters = tileWidth * numTiles.x;
        this.totalHeightMeters = tileWidth * numTiles.y;

        this.xmin = -this.totalWidthMeters / 2;
        this.zmin = -this.totalHeightMeters / 2;
        this.xmax = this.totalWidthMeters / 2;
        this.zmax = this.totalHeightMeters / 2;

        for (let y = 0; y < this.numTiles.y; y++) {
            for (let x = 0; x < this.numTiles.x; x++) {
                const mesh = this.makeSingleTileMesh(x, y, this.meshPrecision);
                const t = new Tile(mesh, this);
                this.ourTiles.push(t);
            }
        }

        this.isGeometrySetup = true;
        this.applyOptimizationOptions();
    }

    protected prettyName(): string {
        return "[Tile] ";
    }

    /**
     * Globe tiles can be reassigned by coordinate because their mesh position
     * is derived from the coordinate itself. Planar tile sets keep their
     * fixed slot assignment for backwards compatibility.
     */
    protected reuseRasterTilesOnUpdate(): boolean {
        return false;
    }

    /** Allows multi-layer tile sets to nominate a single attribution owner. */
    protected showRasterAttribution(): boolean {
        return true;
    }

    /** Bounded parallel raster requests; each frame scans only the active window. */
    public rasterConcurrency = 6;
    private rasterSortAt = 0;
    public processTileRequests(): void {
        const active = this.tileRequests.filter(request => request.inProgress);
        const waiting = this.tileRequests.filter(request => !request.inProgress);
        const camera = this.scene.activeCamera;
        if (camera && performance.now() >= this.rasterSortAt) {
            this.rasterSortAt = performance.now() + 100;
            const distance = new Map(waiting.map(request => [request, Vector3.DistanceSquared(
                camera.globalPosition, request.mesh.getBoundingInfo().boundingSphere.centerWorld)]));
            const visible = new Set(waiting.filter(request => camera.isInFrustum(request.mesh)));
            waiting.sort((a, b) => Number(visible.has(b)) - Number(visible.has(a)) || distance.get(a)! - distance.get(b)!);
        }
        // Completed downloads must not wait a whole rotation behind unstarted
        // requests. Consume them now and fill their network slots in this frame.
        this.tileRequests = active.concat(waiting);
        const count = Math.min(this.tileRequests.length, this.rasterConcurrency + active.length);
        if (count === 0) { this.processNextTileRequest(); return; }
        for (let i=0; i<count; i++) {
            const request=this.tileRequests[0];
            this.processNextTileRequest();
            if (this.tileRequests[0]===request) this.tileRequests.push(this.tileRequests.shift()!);
        }
    }
    private processNextTileRequest() {
    if (this.isGeometrySetup == false) {
        return;
    }

    if (this.tileRequests.length == 0) {
        if (this.requestsProcessedSinceCaughtUp > 0) {
            console.log(this.prettyName() + "caught up on all tile generation requests! (processed " + this.requestsProcessedSinceCaughtUp + " requests)");
            this.requestsProcessedSinceCaughtUp = 0;
            this.onCaughtUpObservable.notifyObservers(true);
        }
        return;
    }

    //console.log("tile requests remaining in queue: " + this.tileRequests.length);
    const request = this.tileRequests[0];

    if (request.requestType == TileRequestType.LoadTile) {
        if (request.inProgress == false) {
            if (this.tileRequests.filter(r => r.inProgress).length >= this.rasterConcurrency) return;
            console.log(this.prettyName() + "trying to load tile raster: " + request.tileCoords);
            request.texture = new Texture(request.url, this.scene);
            request.inProgress = true;

            if (this.ourRasterProvider.retrievalLocation == RetrievalLocation.Remote_and_Save) {
                this.ourRasterProvider.doTileSave(request)
            }
        }
        if (request.inProgress == true) {
            if (request.texture) {
                if (request.texture.isReady()) {
                    console.log(this.prettyName() + "tile raster is ready: " + request.tileCoords);

                    const material = request.mesh.material as StandardMaterial;
                    material.unfreeze();

                    material.diffuseTexture = request.texture;
                    material.diffuseTexture.anisotropicFilteringLevel = this.engine.getCaps().maxAnisotropy;
                    material.diffuseTexture.wrapU = Texture.CLAMP_ADDRESSMODE;
                    material.diffuseTexture.wrapV = Texture.CLAMP_ADDRESSMODE;
                    material.diffuseTexture.hasAlpha = this.hasAlpha;

                    if (this.optimizationOptions.freezeRasterMaterials) {
                        material.freeze();
                    } else {
                        material.unfreeze();
                    }

                    request.mesh.setEnabled(this.isTileGeometryReady(request.tile)); //show ready geometry
                    this.requestsProcessedSinceCaughtUp++;
                    this.tileRequests.shift(); //pop request off front of queue
                    return;
                }
                if (request.texture.loadingError) {
                    console.warn(this.prettyName() + "error loading texture for tile: " + request.tileCoords);
                    request.texture.dispose();

                    this.requestsProcessedSinceCaughtUp++;
                    this.tileRequests.shift(); //pop request off front of queue
                    return;
                }
            }
        }
    }
}

    public getAdvancedDynamicTexture(): AdvancedDynamicTexture {
    return this.ourAttribution.advancedTexture;
}

    public makeSingleTileMesh(x: number, y: number, precision: number): Mesh {
    const ground = MeshBuilder.CreateGround("tile", { width: this.tileWidth, height: this.tileWidth, updatable: true, subdivisions: precision }, this.scene);
    ground.position.z = this.zmin + (y + 0.5) * this.tileWidth;
    ground.position.x = this.xmin + (x + 0.5) * this.tileWidth;

    return ground;
}

    public isBuildingDuplicate(newBuilding: TileBuilding) {
    for (let t of this.ourTiles) {
        for (let existingBuilding of t.buildings) {
            if (existingBuilding.isBBoxContainedOnTile) {
                continue; //don't need to consider buildings fully contained on a tile
            } else {
                if (existingBuilding.doVerticesMatch(newBuilding)) {
                    return true;
                }
            }
        }
    }
    return false;
}

    public disableGroundCulling() {
    this.assertGeometrySetup("disable ground culling");
    for (let t of this.ourTiles) {
        t.mesh.alwaysSelectAsActiveMesh = true;
    }
}

    public setRasterProvider(rp: Raster) {
    this.rasterVersion++;
    this.ourRasterProvider = rp;
}

    /**
    * update all the tiles in the tileset
    * @param lat latitude. conceptually the y position in decimal
    * @param lon longitude. conceptually the x position in decimal
    * @param zoom standard tile mapping zoom levels 0 (whole earth) - 20 (building)
    */
    public updateRaster(lat: number, lon: number, zoom: number) {
    this.assertGeometrySetup("update raster");

    if (!this.reuseRasterTilesOnUpdate()) this.cancelPendingRasterRequests();

    this.zoom = zoom;
    this.centerCoords = new Vector2(lon, lat);
    this.tileCorner = this.ourTileMath.computeCornerTile(this.centerCoords, EPSG_Type.EPSG_4326, this.zoom);
    this.tileScale = this.ourTileMath.computeTileScale();
    this.isRasterSetup = true;


    if (this.showRasterAttribution()) {
        this.ourAttribution.addAttribution(this.ourRasterProvider.name);
    }

    //console.log("Tile Base: " + this.tileCorner);

    const previousTilesByCoordinate = new Map(this.ourTilesMap);
    this.ourTilesMap.clear();

    const desiredCoordinates: Vector3[] = [];
    for (let y = 0; y < this.numTiles.y; y++) {
        for (let x = 0; x < this.numTiles.x; x++) {
            const tileX = this.tileCorner.x + x;
            const tileY = this.tileCorner.y - y;
            desiredCoordinates.push(new Vector3(tileX, tileY, this.zoom));
        }
    }

    if (!this.reuseRasterTilesOnUpdate()) {
        for (let tileIndex = 0; tileIndex < desiredCoordinates.length; tileIndex++) {
            const coordinate = desiredCoordinates[tileIndex];
            this.updateSingleRasterTile(this.ourTiles[tileIndex], coordinate.x, coordinate.y);
        }
        return;
    }

    const unusedTiles = new Set(this.ourTiles);
    // Reserve overlaps before recycling: otherwise the first missing tile can
    // steal a loaded tile needed later in the new window.
    const reserved = new Set(desiredCoordinates.map(c => previousTilesByCoordinate.get(c.toString())).filter(Boolean));
    const reassignedTiles: Tile[] = [];

    for (const coordinate of desiredCoordinates) {
        const coordinateKey = coordinate.toString();
        let tile = previousTilesByCoordinate.get(coordinateKey);

        if (tile === undefined || !unusedTiles.has(tile)) {
            tile = Array.from(unusedTiles).find(candidate => !reserved.has(candidate));
        }
        if (tile === undefined) {
            throw new Error("Unable to assign a mesh for every raster tile coordinate.");
        }

        unusedTiles.delete(tile);
        reassignedTiles.push(tile);

        const hasLoadedRaster = tile.tileCoords?.equals(coordinate)
            && this.tileRasterVersion.get(tile) === this.rasterVersion
            && ((tile.mesh.isEnabled() && !!tile.material?.diffuseTexture)
                || this.tileRequests.some(r => r.tile === tile));

        if (hasLoadedRaster) {
            this.ourTilesMap.set(coordinateKey, tile);
        } else {
            this.updateSingleRasterTile(tile, coordinate.x, coordinate.y);
        }
    }

    this.ourTiles = reassignedTiles;
}

    private cancelPendingRasterRequests(): void {
    for (const request of this.tileRequests) {
        if (request.texture && request.tile.material?.diffuseTexture !== request.texture) {
            request.texture.dispose();
        }
    }
    this.tileRequests = [];
}

    private clearTileRequests(tile?: Tile): void {
        this.tileRequests = this.tileRequests.filter((request) => {
            if (tile && request.tile !== tile) return true;
            request.texture?.dispose();
            return false;
        });
    }

    private updateSingleRasterTile(tile: Tile, tileX: number, tileY: number) {
    this.clearTileRequests(tile);
    if (tile.tileCoords && this.ourTilesMap.get(tile.tileCoords.toString()) === tile) {
        this.ourTilesMap.delete(tile.tileCoords.toString());
    }
    if (tile.tileCoords && !tile.tileCoords.equals(new Vector3(tileX, tileY, this.zoom))) {
        tile.deleteBuildings();
        tile.clearTerrainLOD();
        tile.terrainLoaded = false;
        tile.elevationHeights = undefined;
    }
    tile.tileCoords = new Vector3(tileX, tileY, this.zoom); //store for later     
    this.ourTilesMap.set(tile.tileCoords.toString(), tile);

    this.tileRasterVersion.set(tile, this.rasterVersion);
    tile.mesh.setEnabled(false);
    let material: StandardMaterial;

    if (tile.material) {
        material = tile.material;
        material.unfreeze();

        const texture = material.diffuseTexture;

        if (texture) { //get rid of texture if it already exists  
            texture.dispose();
        }
    }
    else {
        material = new StandardMaterial("material" + tileX + "-" + tileY, this.scene);
        material!.specularColor = new Color3(0, 0, 0);
        material.alpha = 1.0;

        tile.mesh.material = material;
        tile.material = material;
        // material.backFaceCulling = false;
    }

    let url: string = "";

    url = this.ourRasterProvider.getRasterURL(new Vector2(tileX, tileY), this.zoom);

    const request: TileRequest = {
        requestType: TileRequestType.LoadTile,
        tile: tile,
        tileCoords: tile.tileCoords.clone(),
        url: url,
        mesh: tile.mesh,
        texture: null,
        inProgress: false
    }
    this.tileRequests.push(request);
    console.log(this.prettyName() + "submitted tile raster load request for: " + tile.tileCoords);

    tile.mesh.name = "Tile_" + tileX + "_" + tileY;
}

    /**
    * moves all the tiles in the set. when a tile reaches the edge, it is moved
    * to the opposite side of the tileset, e.g. a tile comes off the right 
    * edge and moves to the left edge. useful for trying to achieve an endless
    * scrolling type effect, where the user doesn't move but the ground 
    * underneath does
    * @param movX x, ie left-right amount to move
    * @param movZ z, ie forward-back amount to move 
    * @param reloadLimitPerFrame limit how many tiles we update per frame, to prevent stuttering
    * @param buildingCreator should we spawn buildings on the new tile?
    * @param reloadTerrain should terrain be requested again for recycled tiles?
    */
    public moveAllTiles(
        movX: number,
        movZ: number,
        reloadLimitPerFrame: number,
        buildingCreator: Buildings | null,
        reloadTerrain = false,
    ) {
    this.assertRasterSetup("move tiles");
    if (!Number.isFinite(movX) || !Number.isFinite(movZ)) {
        throw new RangeError("Tile movement must be finite.");
    }
    if (!Number.isInteger(reloadLimitPerFrame) || reloadLimitPerFrame < 0) {
        throw new RangeError("reloadLimitPerFrame must be a non-negative integer.");
    }
    for (const t of this.ourTiles) {
        t.mesh.position.x += movX;
        t.mesh.position.z += movZ;
        t.refreshBoundingBox();
    }

    if (reloadLimitPerFrame === 0) return;
    let tilesReloaded = 0;

    for (const t of this.ourTiles) {
        if (t.mesh.position.x < this.xmin) {
            console.log("Tile: " + t.tileCoords + " is below xMin");
            this.moveHelper(t, new Vector3(this.totalWidthMeters, 0, 0), new Vector3(this.numTiles.x, 0, 0), buildingCreator, reloadTerrain);

            tilesReloaded++;
            if (tilesReloaded >= reloadLimitPerFrame) {
                return;
            }
        }

        if (t.mesh.position.x > this.xmax) {
            console.log("Tile: " + t.tileCoords + " is above xMax");

            this.moveHelper(t, new Vector3(-this.totalWidthMeters, 0, 0), new Vector3(-this.numTiles.x, 0, 0), buildingCreator, reloadTerrain);

            tilesReloaded++;
            if (tilesReloaded >= reloadLimitPerFrame) {
                return;
            }
        }
        if (t.mesh.position.z < this.zmin) {
            console.log("Tile: " + t.tileCoords + " is below zmin");

            this.moveHelper(t, new Vector3(0, 0, this.totalHeightMeters), new Vector3(0, -this.numTiles.y, 0), buildingCreator, reloadTerrain);

            tilesReloaded++;
            if (tilesReloaded >= reloadLimitPerFrame) {
                return;
            }
        }
        if (t.mesh.position.z > this.zmax) {
            console.log("Tile: " + t.tileCoords + " is above zmax");

            this.moveHelper(t, new Vector3(0, 0, -this.totalHeightMeters), new Vector3(0, this.numTiles.y, 0), buildingCreator, reloadTerrain);

            tilesReloaded++;
            if (tilesReloaded >= reloadLimitPerFrame) {
                return;
            }
        }
    }
}

    private moveHelper(
        t: Tile,
        meshMoveAmount: Vector3,
        tileCoordAdjustment: Vector3,
        buildingCreator: Buildings | null,
        reloadTerrain: boolean,
    ) {

    t.deleteBuildings();

    t.mesh.position.addInPlace(meshMoveAmount);
    t.refreshBoundingBox();
    const previousTileCoords = t.tileCoords.clone();
    this.ourTilesMap.delete(t.tileCoords.toString());

    let newTileCoords = t.tileCoords.add(tileCoordAdjustment);
    this.updateSingleRasterTile(t, newTileCoords.x, newTileCoords.y);

    if (buildingCreator) {
        buildingCreator.SubmitLoadTileRequest(t);
    }
    if (reloadTerrain) {
        void this.ourTerrainMB.updateSingleTerrainTile(t).catch((error) => {
            console.error("Unable to reload terrain for recycled tile:", error);
        });
    }

    this.onTilePositionUpdatedObservable.notifyObservers({
        tile: t,
        previousTileCoords,
        tileCoords: t.tileCoords.clone(),
    });
}

    public async generateTerrain(exaggeration: number) {
    this.assertRasterSetup("generate terrain");
    await this.ourTerrainMB.updateAllTerrainTiles(exaggeration);
}

    /**
     * Adds distance-based terrain LOD levels. Reduced meshes inherit the
     * stitched borders of the detailed terrain and use skirts to hide cracks
     * where adjacent tiles select different LOD levels.
     *
     * A precision of 0 hides the tile at that distance and must be the final
     * level. Existing terrain LOD levels created by this method are replaced.
     */
    public setupTerrainLOD(precisions: number[], distances: number[], skirtDepth = this.tileWidth) {
    this.assertGeometrySetup("set up terrain LOD");
    this.ourTerrainMB.setupTerrainLOD(precisions, distances, skirtDepth);
}

    public getTerrainLowestY(): number {
    return this.ourTerrainMB.globalMinHeight;
}
}
